import {icon} from './icons.js?v=20261113';
import {tasks,quiz,math,faqs,countries} from './data.js?v=20261113';
import {payPage,bindPay} from './pay.js?v=20261113';
import {freshProgress,normaliseProgress,checkIn,recordActivity,markHelpSent,dayKey} from './progress.js?v=20261113';
import {art,backdrop,badgesPage,leaderboardPage,notificationsPage,tourScreen} from './experience.js?v=20261113';
import {homeContent,overviewContent,learningContent,illustratedTaskCard} from './upgrades.js?v=20261113';
import {localQuiz,scamQuiz,videoQuiz,lessonSlides,typingPhrase} from './activity-content.js?v=20261113';
import {languageSwitch,setLanguage,translatePublic} from './i18n.js?v=20261113';
let maxTime=10,walletFilter='all',walletDate='',helpSearch='',helpCategory='All',tourStep=0,typingStarted=0,typingTimer=null,videoTimer=null,videoStep=0,announcement='',installPrompt=null;
const memberRoutes=['dashboard','tasks','games','wallet','team','learning','messages','settings','achievements','leaderboard','notifications','security'];
function getProgress(){if(demo)return normaliseProgress(demo.progress);try{return normaliseProgress(JSON.parse(localStorage.getItem('gs-practice-'+user?.id)||'null'));}catch{return freshProgress();}}
function putProgress(p){if(demo){demo.progress=p;save();}else if(user){try{localStorage.setItem('gs-practice-'+user.id,JSON.stringify(p));}catch{toast('Your browser could not save practice progress.');}}}
function logPractice(task,perfect=false){const r=recordActivity(getProgress(),task,{perfect});putProgress(r.progress);if(r.unlocked.length)toast('Badge unlocked: '+r.unlocked.map(b=>b.name).join(', '));return r;}
function helpProgress(){const r=markHelpSent(getProgress());putProgress(r.progress);}
const questionsFor=t=>t.type==='math'?math:t.type==='local'?localQuiz:t.type==='scam'?scamQuiz:t.type==='video'?videoQuiz:quiz;
const passScore=t=>['video','scam'].includes(t.type)?questionsFor(t).length:4;
function clearActivityTimers(){clearInterval(typingTimer);clearInterval(videoTimer);typingTimer=null;videoTimer=null;}

const staticMode=location.hostname.endsWith('.github.io');
const $=(s)=>document.querySelector(s), esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storedDemo=null;try{storedDemo=JSON.parse(localStorage.getItem('gs-demo')||'null');if(storedDemo&&(!Array.isArray(storedDemo.completed)||!Array.isArray(storedDemo.transactions)||!Array.isArray(storedDemo.pending)||!Number.isFinite(storedDemo.balance)||typeof storedDemo.name!=='string'))storedDemo=null;}catch{}
let demo=storedDemo,user=null,filter='All',search='',step=0,answers=[],playing=null;
const money=(v)=>`UGX ${Number(v).toLocaleString('en-UG')}`;
const save=()=>localStorage.setItem('gs-demo',JSON.stringify(demo));
const go=(p)=>{location.hash='/'+p;};
const button=(text,route,cls='primary')=>`<a class="btn ${cls}" href="#/${route}">${text}</a>`;
const logo=(dark=false)=>`<a href="#/" class="brand" aria-label="Glorysake home" translate="no"><img src="./assets/logo-${dark?'dark':'white'}.png" alt=""><span>glorysake<span class="brand-dot">.</span></span></a>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
async function api(path,data,method){const res=await fetch('./api/'+path,{method:method||(data?'POST':'GET'),headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});let body;try{body=await res.json();}catch{throw Error('Account services need the GLORYSAKE server. Explore the demo while hosting is configured.');}if(!res.ok)throw Error(body.error||'Something went wrong. Please try again.');return body;}
function nav(){const cur=location.hash.slice(2).split('?')[0];const links=[['how-it-works','How it works'],['explore','Activities'],['pay','How to pay'],['trust','Why trust us'],['support','Help']].map(([r,t])=>`<a href="#/${r}"${cur===r?' aria-current="page"':''}>${t}</a>`).join('');return `${announcement?`<div class="v-announcement">${esc(announcement)}</div>`:''}${navigator.onLine?'':'<div class="v-offline-status">You’re offline. Saved practice is still here.</div>'}<header class="public-header g-header"><div class="g-wrap g-nav">${logo()}<nav class="desktop-nav" aria-label="Main navigation">${links}</nav><div class="nav-actions">${languageSwitch()}<button class="v-install" data-action="install" hidden>Install app</button>${staticMode?'':'<a class="login-link" href="#/login">Log in</a>'}<a class="g-btn g-btn-primary g-btn-sm" href="#/${staticMode?'demo':'register'}">${staticMode?'Try the demo':'Join free'}</a><button class="g-menu" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-menu" data-action="menu">${icon('menu')}</button></div></div><nav class="mobile-nav g-mobile-nav" id="mobile-menu" hidden aria-label="Mobile navigation">${links}${languageSwitch()}${staticMode?'':'<a href="#/login">Log in</a>'}</nav></header>`;}
function footer(){return `<footer class="g-footer"><div class="g-wrap g-footer-grid"><div class="g-footer-brand">${logo()}<p>Short tasks, practice games and digital skills for Uganda, Kenya and Tanzania.</p></div><nav aria-label="Product"><h2>Product</h2><a href="#/how-it-works">How it works</a><a href="#/explore">Activities</a><a href="#/pay">How to pay</a><a href="#/pricing">Access and availability</a></nav><nav aria-label="Company"><h2>Company</h2><a href="#/about">About Glorysake</a><a href="#/trust">Why trust us</a><a href="#/partners">For partners</a><a href="#/support">Help center</a></nav><nav aria-label="Legal"><h2>Legal</h2><a href="#/terms">Terms of use</a><a href="#/privacy">Privacy notice</a><a href="#/risk">Rewards disclosure</a></nav></div><div class="g-wrap g-footer-base"><p>© ${new Date().getFullYear()} Glorysake. Preview release. Earnings are never guaranteed.</p><p>Fonts: <a href="https://www.onlinewebfonts.com" rel="noopener">Web Fonts</a>, CC BY 4.0${staticMode?'':'. <a href="#/admin">Operations</a>'}</p><button type="button" class="n-motion" data-motion aria-pressed="false">Pause animations</button></div></footer>`;}
function taskCard(t){return illustratedTaskCard(t);}
function menuScreen(id){const t=tasks.find(x=>x.id===id);if(!t)return `<p class="g-dialog-title">Glorysake</p><p>What would you like to try?</p><ol class="g-menu-list">${tasks.map((x,i)=>`<li><button type="button" data-menu="${x.id}"><b>${i+1}</b>${x.short}<span>${x.time}</span></button></li>`).join('')}</ol>`;return `<p class="g-dialog-title">${t.short}</p><p>${t.description}</p><dl><dt>Time</dt><dd>${t.time}</dd><dt>Sample reward</dt><dd class="g-reward">${money(t.reward)}</dd><dt>To complete</dt><dd>${t.criteria.split('. ')[0]}.</dd></dl><ol class="g-menu-list"><li><button type="button" data-menu="go"><b>1</b>Open it in the demo</button></li><li><button type="button" data-menu="root"><b>0</b>Back to the menu</button></li></ol>`;}
function phone(){return `<div class="g-phone" role="group" aria-label="Preview of the Glorysake activity menu"><div class="g-phone-bar" aria-hidden="true"><span>9:41</span><span class="g-phone-cam"></span><span>4G</span></div><div class="g-phone-screen"><div class="g-dialog"><div class="g-dialog-body" id="menu-screen" aria-live="polite">${menuScreen('root')}</div><form class="g-dialog-reply" id="menu-form"><label for="menu-input" class="g-sr">Reply with a number</label><input id="menu-input" inputmode="numeric" autocomplete="off" maxlength="2" placeholder="Reply with a number"><div class="g-dialog-btns"><button type="button" data-menu="root">Cancel</button><button type="submit">Send</button></div></form></div></div></div>`;}
function bindMenu(){const screen=$('#menu-screen'),form=$('#menu-form'),input=$('#menu-input');if(!screen)return;let state='root';const show=v=>{if(v==='go'){go('demo');return;}state=tasks.some(t=>t.id===v)?v:'root';screen.innerHTML=menuScreen(state);};const err=m=>{screen.querySelector('.g-err')?.remove();screen.insertAdjacentHTML('beforeend',`<p class="g-err">${m}</p>`);};$('.g-phone').addEventListener('click',e=>{const b=e.target.closest('[data-menu]');if(!b)return;input.value='';show(b.dataset.menu);});form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const n=input.value.trim();input.value='';if(state==='root'){const t=tasks[Number(n)-1];if(t)show(t.id);else err(`Reply with a number from 1 to ${tasks.length}.`);}else if(n==='1')show('go');else if(n==='0')show('root');else err('Reply 1 to open it, or 0 to go back.');});}
function home(){return nav()+homeContent(phone(),faqMarkup)+footer();}
const faqMarkup=(list)=>list.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('');
function publicPage(kind){const content={
about:['Small tasks, taken seriously.','ABOUT GLORYSAKE','Glorysake is a place to spend spare minutes on something useful: a quiz, a survey, a short lesson. It is built for phones first, for Uganda, Kenya and Tanzania.',`<div class="cards-three">${[['spark','What it is','Short activities with the time, the rules and a sample reward shown before you begin.'],['shield','What it is not','Not an investment, a loan or a betting product. There is no reward for recruiting people and no promised income.'],['clock','Where it stands','This is a preview. Activities are for practice and rewards are virtual until live tasks are funded and approved.']].map(([i,h,p])=>`<article class="panel">${icon(i)}<h3>${h}</h3><p>${p}</p></article>`).join('')}</div><h2 class="space-top">How the money is meant to flow</h2><p>Partners fund an activity with a capped budget. Members complete it under published rules. Submissions are reviewed, and only approved work is paid. Until a partner has funded a task, it is not offered as paid work.</p><h2 class="space-top">Talk to us</h2><p>Questions, corrections and partnership ideas all go through the same queue, and each one gets a reference number.</p><p style="margin-top:20px">${button('Open the help center','support')}</p>`],
'how-it-works':['A little effort. A clear path.','HOW GLORYSAKE WORKS','Explore first. Choose an activity. Read the rules. Complete the work. Follow the review. Every step should make sense.',`<div class="steps-grid">${[['01','Find your fit','Browse skills, surveys, partner activities and practice games.'],['02','Know the details','Each task explains its requirements, time estimate, sample reward and daily limit.'],['03','Follow the outcome','Completed tasks appear in your history. Submitted work stays pending until reviewed.']].map(([n,h,p])=>`<article><span class="step-no">${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="notice">The preview uses practice tasks and virtual rewards. Live opportunities will be listed separately when funded and available.</div>`],
trust:['Clarity is the whole point.','TRUST & TRANSPARENCY','You deserve to understand the opportunity, the requirements and the outcome.',`<div class="cards-three">${[['Clear activity rules','Every task shows the completion criteria, daily cap and review requirements.'],['Visible reward status','Your wallet separates approved rewards from pending reviews. Demo balances never represent real money.'],['Responsible growth','No cash reward for recruitment in this release. No investments, loans or wagering.']].map(([h,p])=>`<article class="panel">${icon('shield')}<h3>${h}</h3><p>${p}</p></article>`).join('')}</div><h2 class="space-top">Built to earn your trust over time.</h2><p>No invented payout counters, fabricated testimonials or income promises. Payment services are unavailable until provider onboarding and market approvals are complete.</p>`],
pricing:['Free to join. Clear from day one.','ACCESS & AVAILABILITY','No activation payment is required or accepted in this preview. Live paid activities will be announced separately when ready.',`<div class="pricing-card"><span class="chip">PREVIEW ACCESS</span><h2>Free<span class="muted"> / to explore</span></h2><p>Explore every preview activity and the member dashboard.</p><ul class="check-list"><li>Practice quizzes and skill games</li><li>Sample task and wallet experience</li><li>Free account registration on server hosting</li><li>No deposit or payment details required</li></ul>${button('Explore the demo','demo')}</div><h2 class="space-top">Country settings</h2><div class="cards-three">${Object.values(countries).map(c=>`<article class="panel"><h3>${c.flag} ${c.name}</h3><p>${c.currency} display preference</p><span class="chip">Live payouts not enabled</span></article>`).join('')}</div>`],
partners:['Meaningful participation. Measurable value.','FOR PARTNERS','Turn your research questions and digital projects into clear, useful activities.',`<div class="steps-grid"><article><span class="step-no">01</span><h3>Define the work.</h3><p>Set eligibility, completion rules, review criteria and a capped budget.</p></article><article><span class="step-no">02</span><h3>Fund the activity.</h3><p>Rewards require confirmed sponsor funding before activities can become available.</p></article><article><span class="step-no">03</span><h3>Review the results.</h3><p>Track submissions, approve valid work and retain a record of every decision.</p></article></div><h2 class="space-top">Plan a campaign.</h2>${supportForm('Partnership enquiry')}`],
terms:['Terms of use','THE DETAILS','Preview terms · Version 10 November 2026',`<div class="legal-copy"><h2>Using the preview</h2><p>Glorysake is currently a product preview. Practice activities and virtual wallet balances have no cash value. Access is intended for people aged 18 or older.</p><h2>Accounts and activity</h2><p>Provide accurate information, protect your login and maintain one account. Do not automate submissions, impersonate others or interfere with the service. Work may be reviewed or rejected against the published task criteria.</p><h2>Rewards and payments</h2><p>No earnings are guaranteed. Task availability and rewards depend on funding, eligibility and approval. No activation payment is required or accepted in this preview. Live deposits and withdrawals are not available. Future paid activities will need their own approved terms before launch.</p><h2>Support and changes</h2><p>Use the help center for account or activity questions. Final operator identity, country-specific terms and dispute policies must be published before any live money launch. These preview terms do not replace those policies.</p></div>`],
privacy:['Your data deserves care.','PRIVACY NOTICE','Preview notice · Version 10 November 2026',`<div class="legal-copy"><h2>What this release stores</h2><p>Server accounts store your name, email, country, password hash, session records and support requests. Passwords are hashed. The browser demo stores sample progress and preferences on your device.</p><h2>Why it is stored</h2><p>Account data supports sign-in, profile settings and support. Task submissions support review. Session cookies are HttpOnly and use SameSite protection. This release does not use advertising trackers.</p><h2>Your choices</h2><p>You can reset device demo progress in settings. Server account export and deletion are available in account settings. Signing out removes the session. Do not send identity documents or payment credentials through the support form.</p><h2>Before public financial launch</h2><p>The operator must publish its legal identity, privacy contact, retention schedule, hosting location and market-specific rights process. No live identity-document collection or payment processing is enabled in this release.</p></div>`],
risk:['Know what you’re joining.','REWARDS DISCLOSURE','Clear expectations make a better experience.',`<div class="legal-copy"><h2>No guaranteed earnings</h2><p>Glorysake does not promise income. Task eligibility, available budgets and quality reviews determine whether any live reward can be earned.</p><h2>Demo balances are virtual</h2><p>All rewards in the interactive demo are examples. They cannot be deposited, transferred, sold or withdrawn. Real accounts begin with a zero balance.</p><h2>No financial products</h2><p>Deposits, investments, loans, interest-bearing plans and cash-stake games are disabled. Referral cash commissions are also disabled.</p><h2>Live payout readiness</h2><p>Live payments require an authorized provider, identity checks, reconciliation, confirmed task funding and completed market approvals. The interface alone does not provide these capabilities.</p></div>`]
}[kind];return `${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head v-page-art">${backdrop(kind==='trust'?'trust-horizon':kind==='partners'?'community-glow':'learning-path')}<h1>${content[0]}</h1><p class="g-lead">${content[2]}</p></header>${content[3]}</div></main>${footer()}`;}
function supportForm(subject=''){if(staticMode)return '<div class="notice">The interactive preview is open. Support enquiries will be available when account services launch.</div>';return `<form id="support-form" class="form-grid"><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Topic<select name="subject"><option>${subject||'General question'}</option><option>Account access</option><option>Task review</option><option>Partnership enquiry</option><option>Privacy request</option></select></label><label class="full">How can we help?<textarea name="message" required minlength="10" maxlength="3000" rows="4"></textarea></label><div class="full"><button class="btn primary" type="submit">Send enquiry ${icon('arrow')}</button><p class="fineprint">Please leave out passwords, OTPs and payment credentials.</p></div><p class="form-error full" role="alert"></p></form>`;}
function support(){return `${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head"><h1>Help center</h1><p class="g-lead">Answers to the questions people ask most. If yours is not here, send us a message.</p></header>${helpControls()}<div class="faqs" id="help-results">${helpResults()}</div><div class="support-grid"><div><h2>Ask us something</h2><p class="muted">Your message goes to the support queue. Keep the reference number we send back.</p></div>${supportForm()}</div></div></main>${footer()}`;}
function explore(app=false){const tools=`<div class="explore-toolbar"><div class="tabs" role="group" aria-label="Activity category">${['All','Skills','Surveys','Games','Partners'].map(x=>`<button class="${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="task-search" aria-label="Search activities" placeholder="Search activities" value="${esc(search)}"></label></div><div class="v-time-filter"><label for="time-available">${icon('clock')} Time available</label><select id="time-available"><option value="2" ${maxTime===2?'selected':''}>Up to 2 minutes</option><option value="5" ${maxTime===5?'selected':''}>Up to 5 minutes</option><option value="10" ${maxTime===10?'selected':''}>Up to 10 minutes</option></select><span class="v-result-count" id="result-count" role="status">${matchingTasks().length} activities to explore</span></div><div class="cards-three" id="task-list">${filteredTasks()}</div>`;if(app)return `<main id="main"><p class="v-eyebrow">FOLLOW YOUR CURIOSITY</p><h1>Find your next little challenge.</h1><p class="page-lead">Eleven ways to learn, notice and try something new. Every activity starts with clear rules.</p>${tools}<p class="fineprint">Practice activities with virtual rewards. They cannot be withdrawn.</p></main>`;return `${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head v-page-art">${backdrop('activity-orbit')}<p class="v-eyebrow">FOLLOW YOUR CURIOSITY</p><h1>Activities</h1><p class="g-lead">Eleven little challenges. A few spare minutes. Where will curiosity take you?</p></header>${tools}<p class="g-fine">Practice activities. Rewards are virtual samples and cannot be withdrawn.</p></div></main>${footer()}`;}
function matchingTasks(){return tasks.filter(t=>(filter==='All'||t.category===filter)&&parseInt(t.time)<=maxTime&&[t.name,t.short,t.description].join(' ').toLowerCase().includes(search.toLowerCase()));}
function filteredTasks(){const list=matchingTasks();return list.length?list.map(taskCard).join(''):`<section class="panel v-empty">${art('quiz')}<h2>A little space to try again.</h2><p>Try another category or allow a little more time.</p><button class="btn outline" data-action="clear-filters">Clear filters</button></section>`;}
function updateTaskList(){if($('#task-list'))$('#task-list').innerHTML=filteredTasks();if($('#result-count'))$('#result-count').textContent=matchingTasks().length+' activities to explore';}
function authPage(register){return `${nav()}<main id="main" class="auth-layout"><div class="auth-story"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>Good things<br>start with<br><em>showing up.</em></h1><p>One account. A little curiosity.<br>A world of small possibilities.</p><img src="./assets/logo-white.png" alt="" class="auth-mark"></div><div class="auth-form-wrap"><span class="eyebrow">${register?'MAKE YOURSELF AT HOME':'GOOD TO HAVE YOU BACK'}</span><h2>${register?'Your story starts here.':'Welcome back.'}</h2><p class="muted">${register?'Create your free Glorysake account.':'Pick up where you left off.'}</p><form id="auth-form" data-register="${register}">${register?'<label>Your name<input name="name" autocomplete="name" required maxlength="80" placeholder="How should we call you?"></label>':''}<label>Email address<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label>Password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required placeholder="${register?'At least 12 characters':'Enter your password'}"></label>${register?`<label>Your country<select name="country">${Object.entries(countries).map(([k,c])=>`<option value="${k}">${c.flag} ${c.name}</option>`).join('')}</select></label><label class="checkbox"><input type="checkbox" name="consent" required><span>I am 18 or older and agree to the <a href="#/terms">Terms</a> and <a href="#/privacy">Privacy notice</a>.</span></label>`:''}<p class="form-error" role="alert"></p><button class="btn primary full-width" type="submit">${register?'Create free account':'Log in'} ${icon('arrow')}</button></form><p class="auth-switch">${register?'Already feel at home? <a href="#/login">Log in</a>':'New here? <a href="#/register">Create an account</a>'}</p><div class="divider"><span>or get a feel for it first</span></div>${button('Explore the interactive demo','demo','outline full-width')}<p class="fineprint">Preview release. No activation fees or live cash rewards.</p></div></main>${footer()}`;}
function ensureDemo(){if(!demo){demo={name:'Alex',country:'UG',completed:[],transactions:[],pending:[],balance:0};save();}}
const appNav=[['dashboard','grid','Overview'],['tasks','spark','Activities'],['games','bolt','Games'],['wallet','wallet','Wallet'],['team','users','Invite friends'],['learning','book','Learn'],['messages','message','Help'],['achievements','medal','Achievements'],['leaderboard','trophy','Practice board'],['security','shield','Security'],['settings','settings','Settings']];
function shell(route,content){const who=demo||user||{name:'Member'};return `<div class="app-layout"><aside class="sidebar">${logo()}<nav aria-label="Member navigation">${appNav.map(([p,i,n])=>`<a href="#/${p}" class="${route===p?'selected':''}">${icon(i)}<span>${n}</span>${p==='tasks'?`<small>${tasks.length}</small>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="preview-card">${icon('spark')}<strong>Practice mode</strong><p>${demo?'You’re in the demo. Your rewards are virtual.':'Your account is ready. Live tasks are not open yet.'}</p><a href="#/">Back to the website</a></div><button class="text-btn" data-action="logout">${icon('logout')} ${demo?'Leave demo':'Log out'}</button></div></aside><div class="app-body"><header class="app-header"><a class="mobile-brand" href="#/dashboard">${logo().replace(/<a[^>]*>|<\/a>/g,'')}</a><span class="breadcrumb">Your space <span>/</span> ${appNav.find(x=>x[0]===route)?.[2]||'Operations'}</span><div class="app-header-right"><a class="v-notification-link" href="#/notifications" aria-label="Notifications">${icon('bell')}${getProgress().notifications.some(n=>!n.read)?`<small>${getProgress().notifications.filter(n=>!n.read).length}</small>`:''}</a><span class="demo-tag">${demo?'Demo':'Preview'}</span><a href="#/settings" class="profile-badge" aria-label="Account settings">${esc(who.name.charAt(0).toUpperCase())}</a></div></header>${announcement?`<div class="v-announcement">${esc(announcement)}</div>`:''}<div class="preview-banner">${icon('spark')} ${demo?'You are in the demo. Tasks and rewards here are for practice and are not real money.':'This is a preview. Live paid tasks and withdrawals are not open yet.'}${demo?'<button data-action="reset-demo">Reset demo</button>':''}</div><div class="app-content">${content}</div><nav class="bottom-nav" aria-label="Mobile member navigation">${appNav.filter(x=>['dashboard','tasks','wallet','settings'].includes(x[0])).map(([p,i,n])=>`<a href="#/${p}" class="${p===route?'selected':''}">${icon(i)}<span>${p==='wallet'?'Wallet':n.split(' ')[0]}</span></a>`).join('')}</nav></div></div>`;}
function overview(){return overviewContent(demo,user,getProgress());}
function walletRows(){return [...(demo?.transactions||[]).map(t=>({...t,type:'practice',status:'Practice credit'})),...(demo?.pending||[]).map(t=>({...t,id:'PENDING-'+t.id,date:t.submitted,amount:t.reward,type:'pending',status:'Pending practice review'}))].filter(t=>(walletFilter==='all'||t.type===walletFilter)&&(!walletDate||dayKey(new Date(t.date))===walletDate)).sort((a,b)=>new Date(b.date)-new Date(a.date));}
function wallet(){const list=walletRows();return `<main id="main"><p class="v-eyebrow">CLEAR AT EVERY STEP</p><h1>Your wallet, explained.</h1><p class="page-lead">Sample credits, pending reviews and paid amounts stay separate.</p><div class="wallet-summary"><section class="wallet-hero"><span class="balance-label">${demo?'Virtual sample':'Available'} balance</span><h2>${money(demo?.balance||0)}</h2><p>Practice samples have no cash value.</p><button class="btn light small" data-action="withdraw">Withdrawal preview ${icon('arrow')}</button></section><div class="panel"><span class="muted">Pending practice review</span><h2>${money((demo?.pending||[]).reduce((a,t)=>a+t.reward,0))}</h2><p>Not approved. Not available to withdraw.</p></div><div class="panel"><span class="muted">Total paid out</span><h2>UGX 0</h2><p>No live payments in the preview.</p></div></div><div class="section-heading compact"><h2>A record of your practice</h2><button class="btn outline small" data-action="export">${icon('download')} Export CSV</button></div><div class="v-wallet-filters"><label>Entry type<select id="wallet-type"><option value="all">All entries</option><option value="practice" ${walletFilter==='practice'?'selected':''}>Practice credit</option><option value="pending" ${walletFilter==='pending'?'selected':''}>Pending review</option><option value="payment" ${walletFilter==='payment'?'selected':''}>Payments (not enabled)</option></select></label><label>Date<input type="date" id="wallet-date" value="${esc(walletDate)}"></label><button class="text-btn" data-action="clear-wallet-filters">Clear filters</button></div><div class="table-wrap"><table><thead><tr><th>Activity</th><th>Reference</th><th>Date</th><th>Virtual amount</th><th>Status</th><th>Receipt</th></tr></thead><tbody>${list.length?list.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td>${esc(t.id)}</td><td>${new Date(t.date).toLocaleDateString('en-GB')}</td><td>${money(t.amount)}</td><td><span class="chip ${t.type==='practice'?'success':''}">${t.status}</span></td><td><button class="v-receipt" data-receipt="${esc(t.id)}">View</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">No matching entries yet. Try a practice activity.</td></tr>'}</tbody></table></div><div class="notice">${icon('shield')} Live withdrawals are disabled. Practice points and sample credits cannot be exchanged for money.</div></main>`;}
function games(){return `<main id="main"><h1>Games</h1><p class="page-lead">Quick challenges to keep your mind sharp. No stakes and no cash prizes.</p><div class="cards-three">${tasks.filter(t=>t.category==='Games'||t.id==='quiz').map(taskCard).join('')}</div></main>`;}
function team(){return `<main id="main"><h1>Invite friends</h1><p class="page-lead">Learning is better with people you know.</p><div class="dashboard-two"><section class="panel invite-panel"><span class="activity-icon violet">${icon('users')}</span><h2>Share your link</h2><p>Invite a friend to explore Glorysake. There are no referral cash rewards in this release.</p><label>Your invite link<div class="copy-field"><input readonly value="${esc(location.origin+location.pathname+'#/register?ref=explore')}" aria-label="Your invite link"><button class="icon-btn" data-action="copy">${icon('copy')}</button></div></label></section><section class="panel"><h3>Our invite rules</h3><ul class="check-list"><li>Share the opportunity honestly</li><li>No guaranteed income claims</li><li>No activation-fee commissions</li><li>No self-referrals or duplicate accounts</li></ul></section></div></main>`;}
function learning(){return learningContent();}
const helpEntries=faqs.map(([q,a],i)=>({q,a,category:['Activities','Account','Activities','Payments','Account','Safety'][i]}));
function helpResults(){const list=helpEntries.filter(e=>(helpCategory==='All'||e.category===helpCategory)&&[e.q,e.a].join(' ').toLowerCase().includes(helpSearch.toLowerCase()));return list.length?faqMarkup(list.map(e=>[e.q,e.a])):'<div class="notice">No answers match yet. Try another word, or ask us below.</div>';}
function helpControls(){return `<div class="v-help-controls"><label class="search-box">${icon('search')}<input id="help-search" placeholder="Search for an answer" aria-label="Search help" value="${esc(helpSearch)}"></label><div class="tabs" role="group" aria-label="Help category">${['All','Account','Payments','Activities','Safety'].map(c=>`<button data-help-category="${c}" class="${helpCategory===c?'active':''}" aria-pressed="${helpCategory===c}">${c}</button>`).join('')}</div></div>`;}
function ticketsMarkup(tickets){return tickets.length?tickets.map(t=>`<article><div class="v-ticket-status"><small>${esc(t.id)}</small><span class="chip">${esc(t.status||'Saved on this device')}</span></div><h3>${esc(t.subject)}</h3><small>${new Date(t.created_at||t.date).toLocaleDateString('en-GB')}</small></article>`).join(''):'<p class="muted">Your support references will appear here.</p>';}
function messages(){return `<main id="main"><p class="v-eyebrow">WE’RE HERE TO HELP</p><h1>A good place to ask.</h1><p class="page-lead">Find a straight answer, or keep track of a support question.</p>${helpControls()}<div class="faqs wide-faq" id="help-results">${helpResults()}</div><section class="panel space-top"><h2>Your support references</h2><div class="v-tickets" id="support-tickets">${demo?ticketsMarkup(demo.tickets||[]):'<div class="v-skeleton" aria-label="Loading support references"></div>'}</div></section><section class="panel space-top"><h2>Ask us something</h2>${demo?'<p class="v-support-note">Demo only. A practice ticket stays on this device; no message is sent.</p><form id="demo-support-form"><label>Topic<input name="subject" maxlength="100" required></label><label>Your question<textarea name="message" minlength="10" maxlength="1000" required></textarea></label><button class="btn primary" type="submit">Save practice ticket</button></form>':supportForm()}</section></main>`;}
function settings(){const who=demo||user;return `<main id="main"><h1>Make yourself at home.</h1><p class="page-lead">A few details that make this space yours.</p><section class="panel settings-panel"><form id="settings-form"><label>Name<input name="name" value="${esc(who.name)}" required maxlength="80"></label><label>Country<select name="country">${Object.entries(countries).map(([k,c])=>`<option value="${k}" ${k===who.country?'selected':''}>${c.flag} ${c.name}</option>`).join('')}</select></label>${demo?`<label>Phone (optional, stays on this device)<input name="phone" type="tel" autocomplete="tel" maxlength="24" value="${esc(who.phone||'')}"></label>`:''}<p class="fineprint">Country is a profile preference. Practice rewards are always shown in UGX; it does not enable live payments.</p><button class="btn primary" type="submit">Save changes</button><p class="form-error" role="alert"></p></form></section><nav class="v-settings-links" aria-label="More member pages">${appNav.filter(x=>!['dashboard','tasks','wallet','settings'].includes(x[0])).map(([r,i,n])=>`<a href="#/${r}">${icon(i)}${n}</a>`).join('')}</nav><section class="panel settings-panel space-top"><div class="button-row"><button class="btn outline small" data-action="tour">Replay the tour</button><button class="v-install" data-action="install" hidden>Install app</button></div><h3 class="space-top">Your data</h3><p>${demo?'Reset your virtual progress on this device whenever you like.':'Export your account information or permanently delete your account.'}</p><div class="button-row"><button class="btn outline" data-action="${demo?'reset-demo':'account-export'}">${demo?'Reset demo progress':'Export account data'}</button>${demo?'':'<button class="btn danger" data-action="delete-account">Delete account</button>'}</div></section></main>`;}
async function admin(){if(demo||!user||user.role!=='admin')return `${nav()}<main id="main" class="public-page wrap"><span class="eyebrow">GLORYSAKE OPERATIONS</span><h1>A thoughtful platform.<br>A responsible operation.</h1><p class="page-lead">Operator access requires a server account with the admin role.</p>${button('Operator sign in','login')}<div class="notice">No public account can grant itself operator access. Configure the administrator using the server bootstrap command.</div></main>${footer()}`;const data=await api('admin/overview');return shell('admin',`<main id="main"><span class="eyebrow">OPERATIONS</span><h1>A clear view of the work.</h1><div class="cards-three">${[['Registered members',data.users],['Open support requests',data.tickets.length],['Campaign drafts',data.campaigns.length]].map(([n,v])=>`<section class="panel"><span>${n}</span><h2>${v}</h2></section>`).join('')}</div><section class="panel space-top"><h2>Campaign studio</h2><p>Plan funded work. Campaigns are saved as drafts; paid distribution stays disabled until payment and review infrastructure is approved.</p><form id="campaign-form" class="form-grid"><label>Campaign title<input name="title" required maxlength="120"></label><label>Reward budget (UGX)<input name="budget" type="number" min="0" step="1" required></label><label class="full">Completion criteria<textarea name="criteria" minlength="10" required></textarea></label><button class="btn primary">Save draft ${icon('plus')}</button><p class="form-error" role="alert"></p></form>${data.campaigns.map(c=>`<div class="admin-row"><strong>${esc(c.title)}</strong><span>${money(c.budget)}</span><span class="chip">Draft</span></div>`).join('')}</section><section class="panel space-top"><h2>Support inbox</h2>${data.tickets.length?data.tickets.map(t=>`<article class="support-ticket"><span class="chip">${esc(t.status)}</span><h3>${esc(t.subject)}</h3><small>${esc(t.name)} · ${esc(t.email)} · ${esc(t.id)}</small><p>${esc(t.message)}</p>${t.status==='open'?`<button class="btn outline small" data-resolve="${esc(t.id)}">Mark resolved</button>`:''}</article>`).join(''):'<p>No requests yet.</p>'}</section><section class="panel space-top"><h2>Public announcement</h2><p>A short plain-text update. Leave blank to clear it.</p><form id="announcement-form"><label>Announcement<textarea name="text" maxlength="240">${esc(announcement)}</textarea></label><button class="btn primary" type="submit">Publish announcement</button><p class="form-error" role="alert"></p></form></section><section class="panel space-top"><h2>Audit trail</h2>${data.audits.map(a=>`<div class="admin-row"><span>${esc(a.action)}</span><small>${esc(a.created_at)}</small></div>`).join('')}</section></main>`);}
function openModal(html){clearActivityTimers();const el=$('#modal');el.innerHTML=`<button class="modal-close icon-btn" aria-label="Close dialog" data-action="close">${icon('close')}</button>${html}`;el.showModal();}
function taskDetail(id){const t=tasks.find(t=>t.id===id);if(!t)return;openModal(`<span class="activity-icon ${t.color}">${icon(t.icon)}</span><p class="q-count">${t.category} practice activity</p><h2 id="modal-title">${t.short}</h2><p>${t.description}</p><div class="task-detail-stats"><div><small>Sample reward</small><strong>${money(t.reward)}</strong></div><div><small>Time estimate</small><strong>${t.time}</strong></div></div><h3>What’s involved</h3><p>${t.criteria}</p><div class="notice">Demo only. Virtual rewards have no cash value. One practice credit per activity on this device.</div><button class="btn primary full-width" data-start="${t.id}">${demo?.completed.includes(t.id)?'Practice again':'Start'}</button>`);}
function startTask(id){clearActivityTimers();if(!tasks.some(t=>t.id===id))return;if(!demo){$('#modal').close();ensureDemo();go('tasks');toast('You’re in the practice demo. Nothing here involves real money.');}playing=tasks.find(t=>t.id===id);step=0;answers=[];if(['quiz','math','local','scam'].includes(playing.type))renderQuestion();else if(playing.type==='video')startVideo();else if(playing.type==='typing')startTyping();else if(playing.type==='app-review')startAppReview();else if(playing.type==='color')colorRound();else if(playing.type==='learn')lesson('learn');else openModal(`<p class="q-count">Practice ${playing.category.toLowerCase()}</p><h2 id="modal-title">${playing.short}</h2><form id="practice-form">${playing.type==='survey'?'<label>How do you usually discover new products?<select name="discovery" required><option value="">Choose one</option><option>Friends and family</option><option>Social media</option><option>Shops and markets</option><option>Online search</option></select></label><label>What matters most when choosing a product?<select name="priority" required><option value="">Choose one</option><option>Quality</option><option>Price</option><option>Recommendations</option><option>Convenience</option></select></label><label>Tell us why (at least 20 characters)<textarea name="proof" required minlength="20" maxlength="1000"></textarea></label>':'<img class="review-image" src="./assets/community.webp" alt="Sample cafe photograph for image review"><label>Describe two quality observations (at least 20 characters)<textarea name="proof" required minlength="20" maxlength="1000"></textarea></label>'}<p class="fineprint">Practice submission only. No personal or sensitive information.</p><button class="btn primary full-width">Submit for practice review ${icon('arrow')}</button></form>`);}
function renderQuestion(){const set=questionsFor(playing),q=set[step];openModal(`<p class="q-count">${playing.short}: question ${step+1} of ${set.length}</p><div class="progress-track"><span style="width:${(step+1)/set.length*100}%"></span></div><h2 id="modal-title">${q.q}</h2><div class="answer-options">${q.a.map((a,i)=>`<button data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${a}${icon('chevron')}</button>`).join('')}</div><p class="fineprint">Practice activity. No cash reward.</p>`);}
function finishQuiz(){const set=questionsFor(playing),score=answers.filter((a,i)=>a===set[i].correct).length,passed=score>=passScore(playing);let credited=false;if(passed){if(!demo.completed.includes(playing.id)){credit(playing);credited=true;}logPractice(playing,score===set.length);}openModal(`${art(passed?'quiz':'lesson','v-result-art')}<h2 id="modal-title">${passed?'A little brighter already.':'Curiosity gets better with practice.'}</h2><p>You answered ${score} of ${set.length} correctly. ${passed?'Your practice progress is saved.':'You need '+passScore(playing)+' correct answers. Try again when you feel ready.'}</p>${credited?`<p class="fineprint">${money(playing.reward)} in virtual sample credits added to the demo wallet. No cash value.</p>`:''}<div class="answer-review">${set.map((q,i)=>`<p><strong>${answers[i]===q.correct?'✓':'○'} ${q.q}</strong><br><span>${q.a[q.correct]}</span></p>`).join('')}</div><button class="btn primary full-width" data-action="close">Keep exploring ${icon('arrow')}</button>`);render(false);}
function credit(t){demo.completed.push(t.id);demo.balance+=t.reward;demo.transactions.unshift({id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),name:t.short,amount:t.reward,date:new Date().toISOString()});save();dispatchEvent(new Event('fx:confetti'));}
let targetColor=0;function colorRound(){const palette=['#7c5ce9','#a3d8c2','#f0bc91','#99dbeb'];targetColor=(step*3+1)%4;openModal(`<p class="q-count">Color Match: round ${step+1} of 5</p><h2 id="modal-title">Find the matching shade.</h2><div class="color-target" style="background:${palette[targetColor]}"></div><div class="color-options">${palette.map((c,i)=>`<button data-color="${i}" style="background:${c}" aria-label="${['Violet','Mint','Peach','Sky blue'][i]}"></button>`).join('')}</div><p class="fineprint">Practice recognition game. No cash prize.</p>`);}
function lesson(id){let h,p;if(id==='learn'){h='A safer internet starts with small habits.';p='<h3>1. Make passwords unique.</h3><p>Use a long passphrase for each account. A password manager helps you keep track.</p><h3>2. Keep your OTP to yourself.</h3><p>Legitimate support should never need your sign-in code or password.</p><h3>3. Pause before you tap.</h3><p>Check the sender, the URL and the request. A promise of guaranteed income or urgent payment deserves a second look.</p>';}else if(id==='opportunity'){h='Know what you’re giving your time to.';p='<p>Read the task requirements, reward status, review process and daily limit. Avoid any offer that promises guaranteed income or asks you to recruit others to recover a fee. Ask questions before you commit.</p>';}else{h='Three labels. One clearer wallet.';p='<h3>Available</h3><p>Approved rewards eligible for the next supported action.</p><h3>Pending</h3><p>Work submitted, with a review still outstanding.</p><h3>Paid out</h3><p>A withdrawal confirmed by the payment provider. A submitted request alone is not a successful payout.</p>';}openModal(`<p class="q-count">Learn</p><h2 id="modal-title">${h}</h2>${p}${id==='learn'?'<h3>Quick check: should you share an OTP with someone claiming to be support?</h3><div class="answer-options"><button data-learn-answer="wrong">Yes, if they ask politely</button><button data-learn-answer="correct">No. Keep sign-in codes private.</button></div>':'<button class="btn primary" data-action="close">Good to know '+icon('check')+'</button>'}`);}
async function render(scroll=true){const route=(location.hash.slice(2).split('?')[0]||'');if(scroll)window.scrollTo(0,0);let html;if(route==='demo'){ensureDemo();go('dashboard');return;}if(memberRoutes.includes(route)){if(!demo&&!user){go('login');return;}const pages={dashboard:overview,tasks:()=>explore(true),games,wallet,team,learning,messages,settings,achievements:()=>badgesPage(getProgress()),leaderboard:()=>leaderboardPage(getProgress(),demo||user),notifications:()=>notificationsPage(getProgress()),security};html=shell(route,pages[route]());}else if(route==='admin')html=await admin();else if(route==='register'||route==='login'){if(staticMode){go('demo');return;}html=authPage(route==='register');}else if(route==='explore')html=explore();else if(route==='support')html=support();else if(route==='pay')html=payPage({nav,footer,icon,staticMode});else if(['about','how-it-works','trust','pricing','partners','terms','privacy','risk'].includes(route))html=publicPage(route);else if(!route)html=home();else html=`${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head"><h1>That page is not here.</h1><p class="g-lead">The link may be old, or the address may have a typo. These will get you back on track.</p></header><div class="g-actions"><a class="g-btn g-btn-primary" href="#/">Go to the home page</a><a class="g-btn g-btn-secondary" href="#/explore">Browse activities</a><a class="g-btn g-btn-secondary" href="#/support">Open the help center</a></div></div></main>${footer()}`;$('#app').innerHTML=html;document.body.classList.add('site');document.body.classList.toggle('app',[...memberRoutes,'admin'].includes(route));enhance();if(!document.body.classList.contains('app'))translatePublic($('#app'));document.querySelectorAll('[data-action=install]').forEach(b=>b.hidden=!installPrompt);if(route==='messages'&&user&&!demo)api('tickets').then(r=>{if($('#support-tickets'))$('#support-tickets').innerHTML=ticketsMarkup(r.tickets);}).catch(e=>{if($('#support-tickets'))$('#support-tickets').textContent=e.message;});if(route==='security'&&!demo)loadSecurity();if(route==='dashboard'&&demo&&!getProgress().tourSeen){const p=getProgress();p.tourSeen=true;putProgress(p);tourStep=0;openModal(tourScreen(0));}{const names={dashboard:'Your space',about:'About','how-it-works':'How it works',explore:'Activities',pay:'How to pay',trust:'Why trust us',support:'Help center',pricing:'Access and availability',partners:'For partners',terms:'Terms of use',privacy:'Privacy notice',risk:'Rewards disclosure',login:'Log in',register:'Join free'};const n=names[route]||(route?route.charAt(0).toUpperCase()+route.slice(1).replaceAll('-',' '):'');document.title=n?n+' | Glorysake':'Glorysake | Make the in-between minutes count';}}
function enhance(){
bindMenu();
const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;const els=document.querySelectorAll('[data-reveal]');
if(reduce||!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('in'));document.querySelectorAll('[data-count]').forEach(c=>c.textContent=c.dataset.count);}
else{const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;e.target.classList.add('in');const c=e.target.querySelector('[data-count]');if(c)countUp(c);io.unobserve(e.target);}),{threshold:.15});els.forEach(e=>io.observe(e));}
if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!reduce)document.querySelectorAll('.tilt').forEach(c=>{c.addEventListener('pointermove',ev=>{const r=c.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width-.5,y=(ev.clientY-r.top)/r.height-.5;c.style.transform=`perspective(700px) rotateX(${-y*6}deg) rotateY(${x*8}deg) translateY(-4px)`;});c.addEventListener('pointerleave',()=>{c.style.transform='';});});
}
function countUp(el){const n=+el.dataset.count,t0=performance.now();const f=t=>{const p=Math.min(1,(t-t0)/1100);el.textContent=Math.round(n*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(f);};requestAnimationFrame(f);}
bindPay({api,toast,staticMode});
window.addEventListener('scroll',()=>document.querySelector('.public-header')?.classList.toggle('scrolled',scrollY>20),{passive:true});
window.addEventListener('hashchange',()=>{render().catch(e=>toast(e.message));});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){search=e.target.value;updateTaskList();}if(e.target.id==='help-search'){helpSearch=e.target.value;$('#help-results').innerHTML=helpResults();}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-task],[data-lesson]');if(!el)return;try{if(el.dataset.task)taskDetail(el.dataset.task);if(el.dataset.filter){filter=el.dataset.filter;render(false);}if(el.dataset.start)startTask(el.dataset.start);if(el.dataset.lesson)lesson(el.dataset.lesson);if(el.dataset.learnAnswer){if(el.dataset.learnAnswer==='correct'){if(!demo){ensureDemo();go('learning');}if(!demo.completed.includes('learn'))credit(tasks.find(t=>t.id==='learn'));logPractice(tasks.find(t=>t.id==='learn'));openModal('<span class="result-art">'+icon('spark')+'</span><h2 id="modal-title">Good habits. Good progress.</h2><p>You completed the digital skills lesson. Your virtual practice progress is saved.</p><button class="btn primary" data-action="close">Keep exploring</button>');render(false);}else toast('Keep your codes private. Try the other answer.');}if(el.dataset.answer!==undefined){answers.push(Number(el.dataset.answer));step++;step>=questionsFor(playing).length?finishQuiz():renderQuestion();}if(el.dataset.color!==undefined){if(Number(el.dataset.color)!==targetColor){toast('Take another look. Match the target shade.');return;}step++;if(step>=5){if(!demo.completed.includes('color'))credit(tasks.find(t=>t.id==='color'));logPractice(tasks.find(t=>t.id==='color'));openModal('<span class="result-art">✳</span><h2 id="modal-title">A moment of focus. Well spent.</h2><p>You matched all five shades. Your virtual practice progress is saved.</p><button class="btn primary" data-action="close">Keep exploring</button>');render(false);}else colorRound();}if(el.dataset.resolve){await api('admin/tickets/'+el.dataset.resolve,{status:'resolved'},'PATCH');await render(false);toast('Request resolved.');}switch(el.dataset.action){case'menu':{const n=$('.mobile-nav');n.hidden=!n.hidden;el.setAttribute('aria-expanded',String(!n.hidden));if(!n.hidden)n.querySelector('a')?.focus();break;}case'close':clearActivityTimers();$('#modal').close();break;case'logout':if(demo){demo=null;localStorage.removeItem('gs-demo');}else{await api('logout',{});user=null;}go('');break;case'reset-demo':demo=null;localStorage.removeItem('gs-demo');ensureDemo();render(false);toast('A fresh start. Demo progress reset.');break;case'withdraw':withdrawPreview();break;case'legacy-withdraw':openModal('<span class="eyebrow">CLARITY BEFORE CASHOUT</span><h2 id="modal-title">Not quite time for that step.</h2><p>Live withdrawals are not enabled. Demo rewards are virtual and cannot be paid out.</p><div class="withdraw-steps"><span>01 · Confirm eligibility</span><span>02 · Review minimum, fee and net amount</span><span>03 · Verify the payout destination</span><span>04 · Track the provider receipt</span></div><p class="fineprint">Payment provider onboarding and country availability must be complete before launch.</p><button class="btn primary" data-action="close">Got it</button>');break;case'copy':await navigator.clipboard.writeText($('.copy-field input').value);toast('Invite link copied.');break;case'export':download('glorysake-demo-statement.csv','Reference,Activity,Amount UGX,Status,Date\n'+walletRows().map(t=>[t.id,t.name,t.amount,t.status,t.date].map(csv).join(',')).join('\n'),'text/csv');toast('Statement exported.');break;case'account-export':download('glorysake-account.json',JSON.stringify(await api('account/export'),null,2),'application/json');break;case'delete-account':openModal('<h2 id="modal-title">Delete your account?</h2><p>This permanently removes your profile and active sessions. Support audit references may be retained without your profile details.</p><form id="delete-form"><label>Confirm your password<input name="password" type="password" required autocomplete="current-password"></label><p class="form-error" role="alert"></p><button class="btn danger" type="submit">Permanently delete account</button></form>');break;}}catch(err){toast(err.message);}});
const csv=v=>'"'+String(v).replaceAll('"','""')+'"';function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{if(form.id==='auth-form'){const register=form.dataset.register==='true';const result=await api(register?'register':'login',values);user=result.user;demo=null;localStorage.removeItem('gs-demo');go(user.role==='admin'?'admin':'dashboard');toast(register?'Welcome to Glorysake. Make yourself at home.':'Good to have you back.');}if(form.id==='support-form'){const r=await api('support',values);form.reset();helpProgress();toast('Message received. Your reference: '+r.id);openModal(`<h2 id="modal-title">Your message is in.</h2><p>Keep this reference for follow-up:</p><strong>${esc(r.id)}</strong><p>Your request is now in the operations support queue.</p><button class="btn primary" data-action="close">Got it</button>`);}if(form.id==='settings-form'){if(demo){demo.name=values.name.trim();demo.country=values.country;demo.phone=String(values.phone||'').slice(0,24);save();}else user=(await api('account',values,'PATCH')).user;render(false);toast('Your details are updated.');}if(form.id==='practice-form'){logPractice(playing);if(!demo.pending.some(t=>t.id===playing.id)&&!demo.completed.includes(playing.id)){demo.pending.push({id:playing.id,name:playing.short,reward:playing.reward,submitted:new Date().toISOString()});save();}openModal('<span class="result-art">✳</span><h2 id="modal-title">A little effort, recorded.</h2><p>Your practice submission is saved as pending review on this device. No cash has been earned or promised.</p><button class="btn primary" data-action="close">Back to exploring</button>');render(false);}if(form.id==='campaign-form'){await api('admin/campaigns',values);await render(false);toast('Campaign draft saved.');}if(form.id==='delete-form'){await api('account',{password:values.password},'DELETE');user=null;$('#modal').close();go('');toast('Account deleted.');}}catch(err){const error=form.querySelector('.form-error');if(error)error.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
function startTyping(){typingStarted=0;openModal(`<p class="v-eyebrow">TYPING SPRINT</p><h2 id="modal-title">Accuracy finds its rhythm.</h2><p>Start the timer, then type this phrase exactly. You have thirty seconds.</p><div class="v-typing-phrase">${typingPhrase}</div><button class="btn primary" data-action="begin-typing">Start the sprint ${icon('play')}</button><form id="typing-form" hidden><label>Type the phrase<input id="typing-input" name="phrase" autocomplete="off" autocapitalize="off" spellcheck="false" required></label><div class="v-timer"><span id="typing-time" role="timer" aria-label="Time remaining">30 seconds left</span><span>Exact spelling and punctuation</span></div><button class="btn primary" type="submit">Check my phrase ${icon('check')}</button><p class="form-error" role="alert"></p></form>`);}
function startAppReview(){openModal(`<p class="v-eyebrow">APP REVIEW STUDIO</p><h2 id="modal-title">Notice what makes it work.</h2><p>Review this fictional app. Your notes stay in this practice demo.</p><div class="v-review-app"><header><strong>Daylight</strong><span>Fictional app</span></header><h3>A little space for your day.</h3><p>Save a thought. Make a plan. Take a breath.</p><div class="v-mock-card">Today’s intention<br><strong>Make time for something useful.</strong></div><small>Home &nbsp;&nbsp; Notes &nbsp;&nbsp; Your space</small></div><form id="app-review-form"><label>Your rating<select name="rating" required><option value="">Choose a rating</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label><label>One thing that works well<textarea name="positive" required minlength="10" maxlength="400"></textarea></label><label>One thing you would improve<textarea name="improve" required minlength="10" maxlength="400"></textarea></label><button class="btn primary" type="submit">Save practice review ${icon('arrow')}</button></form>`);}
function videoFrame(){const frame=lessonSlides[videoStep];return `${art(frame.glyph)}<h3>${frame.title}</h3><p>${frame.body}</p><span class="v-lesson-status">Chapter ${videoStep+1} of 3 · 10 seconds per chapter</span>`;}
function startVideo(){videoStep=0;openModal(`<p class="v-eyebrow">ILLUSTRATED LESSON · 30 SECONDS</p><h2 id="modal-title">A safer little start.</h2><div class="v-lesson-player" id="lesson-player">${videoFrame()}</div><div class="v-lesson-controls"><button class="btn primary small" data-action="play-lesson">Play lesson ${icon('play')}</button><button class="btn outline small" data-action="lesson-next">Next chapter ${icon('arrow')}</button></div><details><summary>Read the full transcript</summary>${lessonSlides.map(l=>`<h3>${l.title}</h3><p>${l.body}</p>`).join('')}</details><button class="btn primary full-width space-top" data-action="lesson-check">Try the three-question check</button>`);}
function nextVideoFrame(){videoStep=(videoStep+1)%3;if($('#lesson-player'))$('#lesson-player').innerHTML=videoFrame();else clearActivityTimers();}
function withdrawPreview(){openModal(`<p class="v-eyebrow">PREVIEW ONLY</p><h2 id="modal-title">Clarity before cashout.</h2><p>Live withdrawals are not available. Neither practice points nor virtual demo credits can be withdrawn.</p><div class="v-withdraw-preview"><div><small>Minimum</small><strong>Not published</strong></div><div><small>Provider fee</small><strong>Not configured</strong></div><div><small>Payable amount</small><strong>UGX 0</strong></div></div><p>When a verified provider is connected, the minimum, actual fee and net amount will appear before confirmation.</p><button class="btn outline full-width" disabled>Live withdrawals unavailable</button>`);}
function receipt(id){const t=walletRows().find(t=>t.id===id);if(!t)return;openModal(`<p class="v-eyebrow">GLORYSAKE · PRACTICE RECORD</p><h2 id="modal-title">A record of a little effort.</h2><dl class="v-receipt-details"><dt>Reference</dt><dd>${esc(t.id)}</dd><dt>Activity</dt><dd>${esc(t.name)}</dd><dt>Date</dt><dd>${new Date(t.date).toLocaleString('en-GB',{timeZone:'Africa/Kampala'})} EAT</dd><dt>Virtual sample amount</dt><dd>${money(t.amount)}</dd><dt>Status</dt><dd>${t.status}</dd></dl><p>This is a demo practice record. It is not proof of payment, a cash receipt or money owed.</p><div class="button-row"><button class="btn primary" data-action="print-receipt">Print record</button><button class="btn outline" data-download-receipt="${esc(t.id)}">Download text</button></div>`);}
function security(){return `<main id="main"><p class="v-eyebrow">A SAFER SPACE</p><h1>Your account. Your control.</h1><p class="page-lead">Keep sign-in details private and know which sessions are open.</p><div class="v-security-grid"><section class="panel"><h2>Signed-in sessions</h2><div id="sessions-list">${demo?'<p>This is a device-local demo. It has no password or server sessions.</p>':'<div class="v-skeleton" aria-label="Loading sessions"></div>'}</div>${demo?'':`<form id="logout-all-form"><label>Current password<input type="password" name="password" autocomplete="current-password" required></label><button class="btn outline" type="submit">Log out everywhere</button><p class="form-error" role="alert"></p></form>`}</section><section class="panel"><h2>${demo?'Keep the good habits':'Change your password'}</h2>${demo?'<p>Real accounts have password and session controls on server hosting. The demo never asks for a password.</p>':`<form id="password-form"><label>Current password<input name="currentPassword" type="password" required autocomplete="current-password"></label><label>New password<input name="newPassword" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><button class="btn primary" type="submit">Update password</button><p class="form-error" role="alert"></p></form>`}</section></div><section class="panel space-top"><h2>Spot a fake Glorysake message.</h2><ul class="check-list"><li>Keep passwords, mobile money PINs and OTPs to yourself.</li><li>Open the official site yourself instead of following unexpected links.</li><li>We never promise guaranteed daily income or cash for recruitment.</li><li>No activation payment is required or accepted in this preview.</li></ul><button class="btn outline small" data-start="scam">Practise spotting a scam ${icon('arrow')}</button></section></main>`;}
async function loadSecurity(){try{const r=await api('security');if($('#sessions-list'))$('#sessions-list').innerHTML=r.sessions.map(s=>`<div class="v-session"><div><strong>${s.current?'This browser':'Another signed-in browser'}</strong><small>Expires ${new Date(s.expiresAt).toLocaleDateString('en-GB')}</small></div><span class="chip">${s.current?'Current':'Active'}</span></div>`).join('');}catch(e){if($('#sessions-list'))$('#sessions-list').textContent=e.message;}}
document.addEventListener('change',e=>{if(e.target.id==='time-available'){maxTime=Number(e.target.value);updateTaskList();}if(e.target.id==='wallet-type'){walletFilter=e.target.value;render(false);}if(e.target.id==='wallet-date'){walletDate=e.target.value;render(false);}if(e.target.matches('[data-language]')){setLanguage(e.target.value);render(false);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){clearActivityTimers();const n=$('.mobile-nav');if(n&&!n.hidden){n.hidden=true;const b=$('[data-action=menu]');b.setAttribute('aria-expanded','false');b.focus();}}});
$('#modal').addEventListener('close',clearActivityTimers);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
if(b.dataset.helpCategory){helpCategory=b.dataset.helpCategory;document.querySelectorAll('[data-help-category]').forEach(x=>{x.classList.toggle('active',x.dataset.helpCategory===helpCategory);x.setAttribute('aria-pressed',x.dataset.helpCategory===helpCategory);});$('#help-results').innerHTML=helpResults();}
if(b.dataset.receipt)receipt(b.dataset.receipt);
if(b.dataset.downloadReceipt){const t=walletRows().find(t=>t.id===b.dataset.downloadReceipt);if(t)download('glorysake-'+t.id+'.txt',`GLORYSAKE — DEMO PRACTICE RECORD\nReference: ${t.id}\nActivity: ${t.name}\nDate: ${t.date}\nVirtual sample amount: ${money(t.amount)}\nStatus: ${t.status}\n\nNot proof of payment. No cash value.`,'text/plain');}
if(b.dataset.tourNext!==undefined){tourStep=Number(b.dataset.tourNext)+1;if(tourStep>=4){$('#modal').close();toast('You’re all set. Follow your curiosity.');}else openModal(tourScreen(tourStep));}
switch(b.dataset.action){
case'checkin':{const r=checkIn(getProgress());putProgress(r.progress);render(false);toast(r.frozen?'Your weekly freeze protected the streak. Welcome back.':r.added?'You showed up. +20 practice points.':'You’ve already checked in today.');if(r.added)dispatchEvent(new Event('fx:confetti'));break;}
case'tour':tourStep=0;openModal(tourScreen(0));break;
case'skip-tour':$('#modal').close();break;
case'clear-filters':filter='All';search='';maxTime=10;render(false);break;
case'clear-wallet-filters':walletFilter='all';walletDate='';render(false);break;
case'leave-board':{const p=getProgress();p.leaderboard=false;putProgress(p);render(false);toast('You’ve left the practice board.');break;}
case'read-notifications':{const p=getProgress();p.notifications.forEach(n=>n.read=true);putProgress(p);render(false);break;}
case'begin-typing':{typingStarted=performance.now();b.hidden=true;$('#typing-form').hidden=false;$('#typing-input').focus();typingTimer=setInterval(()=>{const left=Math.max(0,30-Math.floor((performance.now()-typingStarted)/1000));if($('#typing-time'))$('#typing-time').textContent=left+' seconds left';if(left<=0){clearActivityTimers();if($('#typing-form')){$('#typing-form button').disabled=true;$('#typing-form .form-error').textContent='Time’s up. Close this activity and try again whenever you like.';}}},250);break;}
case'play-lesson':{if(videoTimer){clearInterval(videoTimer);videoTimer=null;b.textContent='Play lesson';}else{if(videoStep===2){videoStep=0;$('#lesson-player').innerHTML=videoFrame();}b.textContent='Pause lesson';videoTimer=setInterval(()=>{if(videoStep===2){clearInterval(videoTimer);videoTimer=null;b.textContent='Replay lesson';}else nextVideoFrame();},10000);}break;}
case'lesson-next':nextVideoFrame();break;
case'lesson-check':clearActivityTimers();step=0;answers=[];renderQuestion();break;
case'print-receipt':window.print();break;
case'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;document.querySelectorAll('[data-action=install]').forEach(x=>x.hidden=true);}break;
}
}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['typing-form','app-review-form','leaderboard-form','demo-support-form','password-form','logout-all-form','announcement-form'].includes(f.id))return;e.preventDefault();if(f.dataset.busy)return;f.dataset.busy='1';const d=Object.fromEntries(new FormData(f)),submit=f.querySelector('button[type="submit"]');if(submit)submit.disabled=true;try{
if(f.id==='typing-form'){if(!typingStarted||performance.now()-typingStarted>30000)throw Error('Time’s up. Close the activity and try another sprint.');if(d.phrase!==typingPhrase)throw Error('Nearly there. Match every letter and punctuation mark.');clearActivityTimers();if(!demo.completed.includes(playing.id))credit(playing);logPractice(playing,true);openModal(`${art('math','v-result-art')}<h2 id="modal-title">Found your rhythm.</h2><p>A perfect little phrase, inside thirty seconds. Your practice progress is saved.</p><button class="btn primary" data-action="close">Keep exploring</button>`);render(false);}
if(f.id==='app-review-form'){if(!demo.pending.some(t=>t.id===playing.id))demo.pending.push({id:playing.id,name:playing.short,reward:playing.reward,submitted:new Date().toISOString()});save();logPractice(playing);openModal(`${art('app-review','v-result-art')}<h2 id="modal-title">A useful pair of observations.</h2><p>Your practice review is recorded on this device. No review was sent to a real app store and no cash was earned.</p><button class="btn primary" data-action="close">Keep exploring</button>`);render(false);}
if(f.id==='leaderboard-form'){const p=getProgress();p.nickname=String(d.nickname).trim().slice(0,24);if(!p.nickname)throw Error('Choose a short nickname.');p.leaderboard=true;putProgress(p);render(false);toast('Your practice board is ready.');}
if(f.id==='demo-support-form'){const ticket={id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),subject:String(d.subject).slice(0,100),date:new Date().toISOString(),status:'Saved on this device'};demo.tickets=demo.tickets||[];demo.tickets.unshift(ticket);save();helpProgress();render(false);toast('Practice reference saved: '+ticket.id);}
if(f.id==='password-form'){await api('account/password',d);f.reset();toast('Password updated. Other sessions have been closed.');loadSecurity();}
if(f.id==='logout-all-form'){await api('security/logout-all',d);user=null;go('login');toast('All sessions have been closed.');}
if(f.id==='announcement-form'){await api('admin/announcement',d);announcement=String(d.text).trim();toast('Announcement updated.');}
}catch(err){const error=f.querySelector('.form-error');if(error)error.textContent=err.message;else toast(err.message);}finally{delete f.dataset.busy;if(submit)submit.disabled=false;}});
addEventListener('gs:payment-demo',e=>{if(!demo)return;const p=getProgress();p.notifications.unshift({id:'payment-'+crypto.randomUUID(),text:'Sample payment '+e.detail.reference+': Needs attention. No provider is connected.',date:new Date().toISOString(),read:false});putProgress(p);});
addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.querySelectorAll('[data-action=install]').forEach(b=>b.hidden=false);});
addEventListener('online',()=>{document.querySelector('.v-offline-status')?.remove();toast('You’re back online.');});
addEventListener('offline',()=>{if(!document.querySelector('.v-offline-status'))$('#app').insertAdjacentHTML('afterbegin','<div class="v-offline-status" role="status">You’re offline. Saved practice activities are still here.</div>');});
if('serviceWorker' in navigator&&location.protocol!=='file:')addEventListener('load',()=>navigator.serviceWorker.register(new URL('./sw.js',import.meta.url),{scope:new URL('./',import.meta.url).pathname}).catch(()=>{}));
const announcementReady=staticMode?Promise.resolve():api('announcement').then(r=>{announcement=r.text||'';}).catch(()=>{});

if(staticMode){render();}else{Promise.all([api('session'),announcementReady]).then(([r])=>{user=r.user;render(false);}).catch(()=>render(false));}
